# Instead: first-seen = scan contracts absent from OLD seen and OLD snapshot. Old snapshot addresses are all current except the 21 newly added entries.
new_addrs = {'0x2b5c0d44878279501aa111e353a2b493e0823b57','0x2eb3f13adb66ef9d0ecdF890d3ba94cb0a8913fe','0x38cb550c1909dabd80a2c6ac6e9e0b107d02052f','0x1bb3701da38d1572984cd200821d1162d6783435','0xb594b29360bd45975608c92dbdba764c508b5c99','0xbbdd8c7720d1eeb1d63738eaabb584a4b72c7777','0xd87adb2e47979d6cb323896b1a9320e0dd132213'} | {a.lower() for _,a,_,_,_,_,_,_,_,_ in scan14}
added = 0
for c in scan['contracts']:
    a = c.get('address','').lower()
    if not a or a in seen_addrs or a in new_addrs or a == '0x60b9262456de011f7d15a54cdd8c48baaa8b022f':
        continue
    # also skip if it was already in old snapshot: check current snapshot entries that are NOT new and NOT reread-only? Old snapshot contracts = current minus new_addrs entries.
    seen['contracts'][c['address']] = c.get('first_block', 131393848)
    added += 1
print('seen appended (non-new-entry first-seen):', added, 'seen total now:', len(seen['contracts']))
json.dump(seen, open(H+'/onchain-scan-seen.json','w'), indent=1)
